class Solution {
public:
    int minimumAddedCoins(vector<int>& coins, int target) {
        sort(coins.begin(), coins.end());
        long long x = 0;
        int ans = 0;
        int i = 0;
        int n = (int)coins.size();
        while (x < target) {
            if (i < n && coins[i] <= x + 1) {
                x += coins[i];
                i++;
            } else {
                x = 2 * x + 1;
                ans++;
            }
        }
        return ans;
    }
};
